// ============================================================================
//  焦点行动想定 · H时同步突击兵力计算
//  代码位置: analysis\gen_routes_v5.py (反推+航线)  moked_scenario\check_eta.py (校验)
// ============================================================================
import math, re, io
from collections import defaultdict

// ================= 一、基础地理计算 =================
def dist_km(a, b):
    /*两点距离(km): 平面近似 + 经度按纬度余弦修正*/
    return math.hypot((a[0]-b[0])*111,
                      (a[1]-b[1])*111*math.cos(math.radians((a[0]+b[0])/2)))

def dms(v, is_lat):
    /*十进制度 -> AFSIM度分秒格式 '30:14:48.00n'*/
    hemi = ('n' if v >= 0 else 's') if is_lat else ('e' if v >= 0 else 'w')
    v = abs(v)
    d = int(v); m = int((v - d) * 60); s = (v - d - m / 60.0) * 3600.0
    if s >= 59.995:
        s = 0.0; m += 1
        if m >= 60: m = 0; d += 1
    return "%d:%02d:%05.2f%s" % (d, m, s, hemi)

def offset(lat, lon, dx_km, dy_km):
    /*从(lat,lon)偏移(dx_km向东, dy_km向北)*/
    return (lat + dy_km / 111.0, lon + dx_km / (111.0 * math.cos(math.radians(lat))))

def polar(lat, lon, az_deg, d_km):
    /*从(lat,lon)沿方位az(0=北顺时针)推进d_km —— 进入/跃升/脱离点计算*/
    return offset(lat, lon, d_km * math.sin(math.radians(az_deg)),
                            d_km * math.cos(math.radians(az_deg)))

// ================= 二、兵力底册: 基地 / 目标 / 编组分配表 =================
IL_BASES = {'RamatDavid': (32.6653, 35.1825), 'TelNof':   (31.8360, 34.8185),
            'Hatzor':     (31.7698, 34.7336), 'Hatzerim': (31.2336, 34.6628),
            'Lod':        (32.0079, 34.8856)}

EG_TGT = {'ElArish': (31.0708, 33.8373), 'JebelLibni': (30.1928, 33.4146),
          'BirGifgafa': (30.4097, 33.1517), 'Fayid': (30.3283, 32.2692),
          'CairoWest': (30.1178, 30.9143),          # ... 15个目标机场
          'Luxor': (25.6711, 32.7069)}

// 战报docx首波分配表: (机型, 数量, 基地, 目标, 航线风格, 禁炸跑道?)
// 航线风格: 'sea'=地中海绕行(主突) / 'direct'=低空直入 / 'saudi'=绕沙特海岸(远程)
STRIKE_PLAN = [
    ('MIRAGE_3CJ',      12, 'Hatzor',     'CairoWest',   'sea',   False),
    ('MYSTERE_IVA',     12, 'TelNof',     'JebelLibni',  'direct', False),
    ('SUPER_MYSTERE_B2', 8, 'Hatzor',     'ElArish',     'direct', True),  // 禁炸跑道
    ('VAUTOUR_IIA',      8, 'RamatDavid', 'Luxor',       'saudi', False),
    // ... 共25个编组 208架次
]

/* 飞机按"距哪个以方基地最近"归池, 编组时从池中依次取机*/
def assign_pools(aircraft):
    pools = defaultdict(lambda: defaultdict(list))
    for a in aircraft:
        bid = min(IL_BASES, key=lambda b: dist_km((a['lat'], a['lon']), IL_BASES[b]))
        pools[bid][a['type']].append(a)
    return pools

// ================= 三、核心算法: H时同时到达 → 起飞时刻反推 =================
H_ARRIVE = 2700.0     // H时到达基准(s): 05:45Z = 当地07:45 (推演开局05:00Z)
V_AVG    = 195.0      // 平均巡航速度(m/s, 约380kt)

def creation_time(base, tgt, style):
    /* 编组起飞时刻 = H时到达基准 - 预计飞行时长*/
    d = dist_km(IL_BASES[base], EG_TGT[tgt])      // 大圆距离
    if style == 'saudi':
        d = d * 1.6 + 200        // 绕沙特海岸大迂回: 航程x1.6 + 200km附加段
    else:
        d = d * 1.35 + 80        // 全员地中海绕行:    航程x1.35 + 80km附加段
    flight_s = d * 1000 / V_AVG  // 预计飞行时长(s)
    ct = H_ARRIVE - flight_s     // ★ 倒推: 起飞时刻 = 到达时刻 - 飞行时长
    ct = max(600.0, min(ct, 1800.0))   // 夹取起飞窗口: 最早07:10 / 最晚07:30
    return ct

// ================= 四、航线几何: 三通过攻击剖面 =================
def make_route(base, tgt, style, ban_runway, ac='MIRAGE_3CJ', idx=0):
    /*
    完整航线: 起飞滑跑 -> 低空100ft突防(走廊绕行) -> 三通过攻击 -> 返航降落
    三通过几何(每机3 passes, 通过间左侧10km绕行再进入):
        进入点6km(100ft) -> 浅跃升点4km(1000ft上抛) -> 目标上空投弹
        -> 脱离点8km(回超低空)
    僚机进入方位 [0,+12,-12,+24]度交叉偏转 -> 多角度切断跑道
    */
    v_lo, v_cr = 450, 420                     // 低空突防/跃升巡航速度(kt)
    blat, blon = IL_BASES[base]
    tlat, tlon = EG_TGT[tgt]
    pts = [(blat, blon, '6 ft agl', '20 kts')]            // 滑跑
    p2 = offset(blat, blon, -3, 2)
    pts.append((p2[0], p2[1], '500 ft agl', '150 kts'))   // 离场
    if style == 'saudi':
        for p in [offset(blat, blon, 20, -80), (27.8, 34.6), (26.8, 33.6)]:
            pts.append((p[0], p[1], '100 ft', '%d kts' % v_lo))   // 绕沙特海岸
    else:
        sea1 = offset(blat, blon, -70, 35)                // 出海点(地中海)
        sea2 = (min(tlat + 0.55, 31.90), max((blon+tlon)/2 - 0.35, 34.00))
        north = (tlat + 0.30, tlon + 0.10)                // 海岸突然南转点
        for p, alt in [(sea1, '100 ft'), (sea2, '100 ft'), (north, '150 ft')]:
            pts.append((p[0], p[1], alt, '%d kts' % v_lo))
    lead = [0.0, 12.0, -12.0, 24.0][idx % 4]              // 僚机方位交叉角
    for k3 in range(3):                                     //★ 三次通过
        entry = polar(tlat, tlon, lead, 6)                 // 进入点6km
        pop   = polar(tlat, tlon, lead, 4)                 // 浅跃升点4km
        exitp = polar(tlat, tlon, lead + 180, 8)           // 脱离点8km(反方位)
        pts += [(entry[0], entry[1], '100 ft', '%d kts' % v_lo),
                (pop[0],   pop[1],   '1000 ft', '%d kts' % v_cr),
                (tlat,     tlon,     '1000 ft', '%d kts' % v_cr),
                (exitp[0], exitp[1], '100 ft', '%d kts' % v_lo)]
        if k3 < 2:
            side = polar(tlat, tlon, lead + 270, 10)       // 左侧10km绕行中继
            pts.append((side[0], side[1], '100 ft', '%d kts' % v_lo))
    back = offset(blat, blon, -10, 10)
    pts.append((back[0], back[1], '2000 ft', '%d kts' % v_cr))          // 返航
    pts.append((blat, blon, '6 ft agl', '120 kts'))                     // 降落
    return pts

// ================= 五、落盘: 反推时刻 + 航线 写成AFSIM想定 =================
def emit_wave(f, pools):
    /*首波: 逐编组反推起飞时刻, 机间+2s紧密梯队; 二波: 落地+450s周转再出动*/
    for (ac, n, base, tgt, style, ban) in STRIKE_PLAN:
        ct = creation_time(base, tgt, style)           // 该编组反推起飞时刻
        got = take(pools, base, ac, n)
        f.write("# %s x%d @%s -> %s (%s, T+%.0fs起飞)\n"
                % (ac, len(got), base, tgt, style, ct))
        for k, a in enumerate(got):
            f.write("platform %s ST_RT_%s%s\n" % (a['nm'], ac, '_NORW' if ban else ''))
            f.write("   creation_time %.0f sec\n" % (ct + k * 2))   # ★ +2s梯队
            f.write(route_text(make_route(base, tgt, style, ban, ac, k)))
            f.write("end_platform\n\n")

    // 二波: 同机再出动等效 —— 落地+450s地面周转, 新实例=满油满弹(扫射弹药档)
    for (ac, n, base, tgt, style, ban) in STRIKE_PLAN:
        d2 = dist_km(IL_BASES[base], EG_TGT[tgt])
        d2 = {'saudi': d2*1.6+200, 'sea': d2*1.35+80}.get(style, d2*1.15)
        w2_ct = H_ARRIVE_2ND - d2 * 1000 / 195.0       // 二波到达窗口同样倒推
        for k in range(n):
            f.write("   creation_time %.0f sec\n" % (w2_ct + k * 2))

// ================= 六、闭环校验: 按真实航点反向核算到达偏差 =================
def check_eta(scen_text):
    /*
    对生成的wave1逐编组沿航点序列分段积分(t += 段距/段速),
    推算实际到达时刻, 与H=2650s比对 -> H_diff(正=早到盘旋, ~0=精确同步)
    */
    H = 2650.0
    rows = []
    for p in parse_platforms(scen_text):               // 正则解析creation_time+航点
        t, t_arr = 0.0, None
        for k in range(len(p['wps']) - 1):
            sp2, alt2 = p['wps'][k+1]['spd'], p['wps'][k+1]['alt']
            if sp2 <= 20:
                continue                               // 滑跑/停机段不计时长
            d = dist_km(p['wps'][k]['pos'], p['wps'][k+1]['pos'])
            t += d / sp2 * 3600.0
            if t_arr is None and alt2 >= 900 and k >= 3:
                t_arr = t                              // 首个跃升航点=到达
        eta = p['ct'] + (t_arr if t_arr else t)
        rows.append((p['tgt'], p['base'], p['ct'], eta, eta - H))
    // 输出: target base takeoff dist_km fly_s eta_s H_diff_s
    for r in sorted(rows, key=lambda x: -x[4]):
        print('%-13s %-11s takeoff=%6d  eta=%8.0f  H_diff=%+9.0f'
              % (r[0], r[1], r[2], r[3], r[4]))

